<script setup lang="ts">
import { computed,onMounted,ref,watch } from 'vue';
import { api } from '@/services/api';
import { formatBRL,formatDateBR,parseMoney } from '@/utils/formatters';
import { format } from 'date-fns';
import AppDialog from '@/components/ui/AppDialog.vue';
import BankLogo from '@/components/ui/BankLogo.vue';
import { Plus,Repeat2,Pencil,Pause,Play } from 'lucide-vue-next';
import type { CreditCard,FinancialAccount,Category } from '@/types';
interface Subscription { id:string;description:string;amount:number;account_id:string;card_id:string|null;category_id:string;frequency:string;next_due_date:string;is_active:boolean;card_name?:string;account_name:string;last_generated_date?:string }
const items=ref<Subscription[]>([]),accounts=ref<FinancialAccount[]>([]),cards=ref<CreditCard[]>([]),categories=ref<Category[]>([]);
const loading=ref(true),saving=ref(false),error=ref(''),formError=ref(''),editing=ref<Subscription|null>(null),showForm=ref(false),charging=ref<Subscription|null>(null);
const today=format(new Date(),'yyyy-MM-dd'),chargeDate=ref(today);
const frequencies:Record<string,string>={MONTHLY:'Mensal',YEARLY:'Anual',WEEKLY:'Semanal'};
const blank=()=>({description:'',amount:'',account_id:'',card_id:'',category_id:'',frequency:'MONTHLY',next_due_date:today,is_active:true});
const form=ref(blank());
const selectedCard=computed(()=>cards.value.find(c=>c.id===form.value.card_id));
watch(selectedCard,card=>{if(card?.account_id)form.value.account_id=card.account_id;});
const active=computed(()=>items.value.filter(s=>s.is_active));
const monthly=computed(()=>active.value.reduce((sum,s)=>sum+Number(s.amount)*(s.frequency==='YEARLY'?1/12:s.frequency==='WEEKLY'?52/12:1),0));
async function load(){loading.value=true;error.value='';try{const [s,a,c,cat]=await Promise.all([api.get('/subscriptions'),api.get('/settings/accounts'),api.get('/cards'),api.get('/settings/categories')]);items.value=s.data;accounts.value=a.data.filter((a:FinancialAccount)=>['CHECKING','SAVINGS','WALLET'].includes(a.account_type));cards.value=c.data.filter((c:CreditCard)=>['CREDIT','MULTIPLE'].includes(c.card_type));categories.value=cat.data.filter((c:Category)=>['DESPESA','AMBOS'].includes(c.type));}catch{error.value='Não foi possível carregar as assinaturas. Tente novamente.';}finally{loading.value=false;}}
function open(item?:Subscription){editing.value=item||null;form.value=item?{description:item.description,amount:String(item.amount),account_id:item.account_id,card_id:item.card_id||'',category_id:item.category_id,frequency:item.frequency,next_due_date:item.next_due_date,is_active:item.is_active}:{...blank(),account_id:accounts.value[0]?.id||'',category_id:categories.value[0]?.id||''};formError.value='';showForm.value=true;}
function payload(s:Subscription){return {description:s.description,amount:s.amount,account_id:s.account_id,card_id:s.card_id,category_id:s.category_id,frequency:s.frequency,next_due_date:s.next_due_date,is_active:!s.is_active};}
async function save(){if(saving.value)return;const amount=parseMoney(form.value.amount);if(!Number.isFinite(amount)||amount<=0){formError.value='Informe um valor positivo.';return;}saving.value=true;try{const data={...form.value,amount,card_id:form.value.card_id||null};if(editing.value)await api.put(`/subscriptions/${editing.value.id}`,data);else await api.post('/subscriptions',data);showForm.value=false;await load();}catch(e:any){formError.value=typeof e.response?.data?.detail==='string'?e.response.data.detail:'Não foi possível salvar. Confira os campos.';}finally{saving.value=false;}}
async function toggle(s:Subscription){if(saving.value)return;saving.value=true;try{await api.put(`/subscriptions/${s.id}`,payload(s));await load();}catch(e:any){error.value=e.response?.data?.detail||'Não foi possível alterar a assinatura.';}finally{saving.value=false;}}
function openCharge(s:Subscription){charging.value=s;chargeDate.value=today;formError.value='';}
async function charge(){if(!charging.value||saving.value)return;saving.value=true;try{await api.post(`/subscriptions/${charging.value.id}/charge`,{expected_date:charging.value.next_due_date,date:chargeDate.value});charging.value=null;await load();}catch(e:any){formError.value=e.response?.data?.detail||'Não foi possível registrar a cobrança.';}finally{saving.value=false;}}
onMounted(load);
</script>
<template>
  <div class="subscriptions-page"><header class="subscription-heading"><div><p class="eyebrow">PLANEJAMENTO</p><h1>Assinaturas</h1><p>Saiba o que se repete e onde cada cobrança vai entrar.</p></div><button class="ui-button primary" :disabled="loading" @click="open()"><Plus :size="20"/>Nova assinatura</button></header>
    <div v-if="error" class="form-error" role="alert">{{ error }} <button class="ui-button" @click="load">Tentar novamente</button></div><p v-if="loading" role="status">Carregando assinaturas…</p>
    <template v-else><section class="subscription-summary"><div><small>Assinaturas ativas</small><strong>{{ active.length }}</strong></div><div><small>Custo mensal estimado</small><strong>{{ formatBRL(monthly) }}</strong></div><p>Valores anuais e semanais são convertidos em uma média mensal. As próximas cobranças são previsões: confirme uma cobrança realizada ou importe a fatura para registrá-la na conta ou no cartão.</p></section>
    <div v-if="!items.length" class="subscription-empty"><Repeat2 :size="36"/><h2>Seus serviços recorrentes, em um lugar</h2><p>Cadastre uma assinatura ou confirme uma sugestão ao importar a fatura. Serviços como Netflix e Spotify podem ser reconhecidos na prévia.</p><RouterLink to="/import" class="ui-button">Importar fatura</RouterLink></div>
    <div class="subscription-list"><article v-for="s in items" :key="s.id" class="subscription-item" :class="{ paused:!s.is_active }"><div class="subscription-identity"><BankLogo :name="cards.find(c=>c.id===s.card_id)?.bank_name || accounts.find(a=>a.id===s.account_id)?.bank_name"/><div><h2>{{ s.description }}</h2><p>{{ s.card_name ? `Crédito · ${s.card_name}` : `Pela conta · ${s.account_name}` }}</p><small>{{ s.is_active ? 'Ativa' : 'Pausada' }} · {{ frequencies[s.frequency] }}</small></div></div><div><strong>{{ formatBRL(s.amount) }}</strong><p>Próxima cobrança: {{ formatDateBR(s.next_due_date) }}</p></div><div class="subscription-actions"><button class="ui-button" :disabled="!s.is_active || s.next_due_date>today || saving" @click="openCharge(s)">Registrar cobrança</button><button class="icon-button" :aria-label="`Editar assinatura ${s.description}`" @click="open(s)"><Pencil :size="20"/></button><button class="icon-button" :disabled="saving" :aria-label="`${s.is_active?'Pausar':'Retomar'} assinatura ${s.description}`" @click="toggle(s)"><Pause v-if="s.is_active" :size="20"/><Play v-else :size="20"/></button></div></article></div></template>
    <AppDialog v-if="showForm" @close="!saving && (showForm=false)"><form class="subscription-form" @submit.prevent="save"><h2>{{ editing?'Editar assinatura':'Nova assinatura' }}</h2><div v-if="formError" class="form-error" role="alert">{{ formError }}</div><label>Nome da assinatura<input v-model="form.description" required maxlength="255" placeholder="Ex.: Netflix"/></label><div class="subscription-fields"><label>Valor da cobrança (R$)<input v-model="form.amount" required inputmode="decimal" placeholder="39,90"/></label><label>Frequência<select v-model="form.frequency"><option v-for="(label,key) in frequencies" :key="key" :value="key">{{ label }}</option></select></label></div><label>Onde é cobrada?<select v-model="form.card_id"><option value="">Diretamente na conta</option><option v-for="c in cards" :key="c.id" :value="c.id">Crédito · {{ c.name }}</option></select></label><label>Conta vinculada<select v-model="form.account_id" required :disabled="!!selectedCard?.account_id"><option v-for="a in accounts" :key="a.id" :value="a.id">{{ a.name }}</option></select></label><div class="subscription-fields"><label>Categoria<select v-model="form.category_id" required><option v-for="c in categories" :key="c.id" :value="c.id">{{ c.name }}</option></select></label><label>Próxima cobrança<input v-model="form.next_due_date" type="date" required min="2000-01-01" max="2100-12-31"/></label></div><p class="field-help">Cadastrar a assinatura não cria despesas futuras. Confirme a cobrança quando ela acontecer ou vincule-a na prévia da fatura.</p><footer><button type="button" class="ui-button" :disabled="saving" @click="showForm=false">Cancelar</button><button class="ui-button primary" :disabled="saving">{{ saving?'Salvando…':'Salvar assinatura' }}</button></footer></form></AppDialog>
    <AppDialog v-if="charging" @close="!saving && (charging=null)"><form class="subscription-form" @submit.prevent="charge"><h2>Registrar cobrança de {{ charging.description }}</h2><p>{{ formatBRL(charging.amount) }} · {{ charging.card_name ? `Entrará na fatura de ${charging.card_name}, conforme o ciclo da data.` : `Será descontado de ${charging.account_name}.` }}</p><p class="field-help">Confirme apenas uma cobrança que já aconteceu. Se você vai importar esta cobrança, vincule a assinatura na prévia para evitar repetição.</p><div v-if="formError" class="form-error" role="alert">{{ formError }}</div><label>Data da cobrança<input v-model="chargeDate" type="date" required :max="today"/></label><footer><button type="button" class="ui-button" :disabled="saving" @click="charging=null">Cancelar</button><button class="ui-button primary" :disabled="saving">{{ saving?'Registrando…':'Confirmar cobrança' }}</button></footer></form></AppDialog>
  </div>
</template>
<style scoped>
.subscriptions-page{display:grid;gap:28px;}.subscription-heading{display:flex;justify-content:space-between;align-items:flex-start;gap:20px;flex-wrap:wrap;}.subscription-heading p{color:var(--muted);margin-top:12px;}.subscription-summary{background:#e8f1ed;border-radius:18px;padding:28px;display:flex;gap:36px;flex-wrap:wrap;}.subscription-summary small{display:block;color:var(--muted);}.subscription-summary strong{display:block;font-size:30px;margin-top:8px;}.subscription-summary p{flex-basis:100%;max-width:90ch;color:var(--muted);line-height:1.7;}.subscription-list{display:grid;gap:16px;}.subscription-item{display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:24px;border:1px solid var(--line);border-radius:16px;padding:24px;background:white;}.subscription-item.paused{opacity:.7;}.subscription-item h2{font-size:20px;}.subscription-item p,.subscription-item small{color:var(--muted);margin-top:6px;line-height:1.5;}.subscription-identity{display:flex;gap:14px;align-items:center;}.subscription-item strong{font-size:24px;}.subscription-actions{display:flex;gap:10px;align-items:center;flex-wrap:wrap;}.subscription-empty{display:grid;justify-items:start;gap:18px;padding:32px;background:white;border:1px solid var(--line);border-radius:18px;}.subscription-empty p{max-width:65ch;color:var(--muted);line-height:1.7;}.subscription-form{padding:28px;display:grid;gap:20px;}.subscription-form h2{font-size:26px;}.subscription-form label{display:grid;gap:8px;font-weight:600;}.subscription-form input,.subscription-form select{width:100%;border:1px solid var(--line);border-radius:10px;padding:12px;font-size:16px;min-height:48px;font-weight:400;}.subscription-fields{display:grid;grid-template-columns:1fr 1fr;gap:16px;}.subscription-form footer{display:flex;justify-content:flex-end;gap:12px;flex-wrap:wrap;}@media(max-width:600px){.subscription-fields{grid-template-columns:1fr;}.subscription-item{padding:20px;}.subscription-summary{padding:24px;gap:24px;}.subscription-actions{width:100%;}.subscription-heading>.ui-button{width:100%;}}
</style>
